```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS callee, c.span_name, count(*) n, round(avg(p.duration)/1e6,1) AS caller_client_ms, round(avg(c.duration)/1e6,2) AS callee_server_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='search' AND p.attr_span_kind='Client' GROUP BY ALL",
          "claim": "search's client spans to rate take about 2577ms, while rate's server spans take about 0.5ms; geo calls stay fast."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, CASE WHEN duration>1e8 THEN 'slow' ELSE 'fast' END speed, count(*) n, round(min(duration)/1e6,1) minms, round(max(duration)/1e6,1) maxms FROM abnormal_traces WHERE service_name='search' AND attr_span_kind='Client' AND span_name='rate.Rate/GetRates' GROUP BY ALL",
          "claim": "Almost all search-to-rate client calls take 1.7 to 5 seconds, with no failures or error status codes."
        },
        {
          "kind": "metric",
          "sql": "SELECT service_name, metric, round(avg(value),1) avgv, round(max(value),1) maxv, count(*) n FROM abnormal_metrics_sum WHERE metric IN ('k8s.pod.network.errors','k8s.pod.network.io') AND service_name IN ('search','rate') GROUP BY ALL",
          "claim": "Pod network io and errors for search and rate show no abnormal change, so the delay is not a transport-level fault."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, c.span_name, count(*) n, round(avg(p.duration)/1e6,1) caller_ms, round(avg(c.duration)/1e6,1) callee_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='frontend' AND c.service_name='search' GROUP BY ALL",
          "claim": "frontend's HTTP /hotels client calls to search average about 2408ms, matching search's own server time of about 2696ms."
        }
      ]
    }
  ]
}
